import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getProperty } from '../services/api';
import { useSaved } from '../context/SavedContext';
import { useAuth } from '../context/AuthContext';
import EnquiryModal from '../components/EnquiryModal';
import { Heart, MapPin, BedDouble, Bath, Maximize2, ArrowLeft, CheckCircle, Phone } from 'lucide-react';
import styles from './PropertyDetailPage.module.css';

export default function PropertyDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const { isSaved, toggle } = useSaved();
  const [property,  setProperty]  = useState(null);
  const [loading,   setLoading]   = useState(true);
  const [activeImg, setActiveImg] = useState(0);
  const [showEnquiry, setShowEnquiry] = useState(false);

  useEffect(() => {
    getProperty(id)
      .then(({ data }) => setProperty(data.property))
      .catch(() => navigate('/'))
      .finally(() => setLoading(false));
  }, [id, navigate]);

  if (loading) return <div className={styles.loading}>Loading property…</div>;
  if (!property) return null;

  const p = property;
  const images = [p.image, ...(p.images || [])].filter(Boolean);
  const saved = isSaved(p.id || p._id);

  const handleSave = () => {
    if (!user) { navigate('/login'); return; }
    toggle(p);
  };

  return (
    <div className={`container ${styles.wrap}`}>
      {/* Back */}
      <button className={styles.back} onClick={() => navigate(-1)}>
        <ArrowLeft size={18} /> Back
      </button>

      <div className={styles.inner}>
        {/* Left: Images + Details */}
        <div className={styles.left}>
          {/* Gallery */}
          <div className={styles.gallery}>
            <div className={styles.mainImgWrap}>
              <img
                src={images[activeImg] || 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=800&q=80'}
                alt={p.title}
                className={styles.mainImg}
              />
              <div className={styles.verified}>
                <CheckCircle size={13} /> Verified
              </div>
              <button
                className={`${styles.saveBtn} ${saved ? styles.saveBtnActive : ''}`}
                onClick={handleSave}
              >
                <Heart size={20} fill={saved ? '#e11d48' : 'none'} color={saved ? '#e11d48' : '#0F172A'} />
              </button>
            </div>
            {images.length > 1 && (
              <div className={styles.thumbRow}>
                {images.map((img, i) => (
                  <img
                    key={i}
                    src={img}
                    alt=""
                    className={`${styles.thumb} ${i === activeImg ? styles.thumbActive : ''}`}
                    onClick={() => setActiveImg(i)}
                  />
                ))}
              </div>
            )}
          </div>

          {/* Description */}
          {p.description && (
            <div className={styles.section}>
              <h2 className={styles.sectionTitle}>About this property</h2>
              <p className={styles.description}>{p.description}</p>
            </div>
          )}

          {/* Amenities */}
          {p.amenities?.length > 0 && (
            <div className={styles.section}>
              <h2 className={styles.sectionTitle}>Amenities</h2>
              <div className={styles.amenities}>
                {p.amenities.map(a => (
                  <span key={a} className={styles.amenity}>✓ {a}</span>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Right: Info Card */}
        <div className={styles.right}>
          <div className={styles.infoCard}>
            {/* Price */}
            <div className={styles.price}>{p.price}</div>
            {p.priceNote && <div className={styles.priceNote}>{p.priceNote}</div>}
            {p.perSqft   && <div className={styles.perSqft}>{p.perSqft}</div>}

            {/* Title & Location */}
            <h1 className={styles.title}>{p.title}</h1>
            <div className={styles.location}>
              <MapPin size={15} />
              <span>{p.location}</span>
            </div>

            {/* Badges */}
            <div className={styles.badgeRow}>
              {p.possession && <span className={styles.possessionBadge}>{p.possession}</span>}
              {(p.badges || []).map((b, i) => (
                <span key={i} className={styles.badge}>{b.label}</span>
              ))}
            </div>

            {/* Specs Grid */}
            <div className={styles.specsGrid}>
              {p.bedroom    && <div className={styles.specItem}><BedDouble size={18} className={styles.specIcon} /><div><div className={styles.specVal}>{p.bedroom.includes('BHK') ? p.bedroom : `${p.bedroom} BHK`}</div><div className={styles.specKey}>Bedrooms</div></div></div>}
              {p.bathroom   && <div className={styles.specItem}><Bath      size={18} className={styles.specIcon} /><div><div className={styles.specVal}>{p.bathroom}</div><div className={styles.specKey}>Bathrooms</div></div></div>}
              {(p.plotSize || p.area) && <div className={styles.specItem}><Maximize2 size={18} className={styles.specIcon} /><div><div className={styles.specVal}>{p.plotSize || p.area}</div><div className={styles.specKey}>Area</div></div></div>}
              {p.propertyType && <div className={styles.specItem}><span className={styles.specIcon} style={{fontSize:18}}>🏠</span><div><div className={styles.specVal}>{p.propertyType}</div><div className={styles.specKey}>Type</div></div></div>}
              {p.furnishingStatus && <div className={styles.specItem}><span className={styles.specIcon} style={{fontSize:18}}>🛋️</span><div><div className={styles.specVal}>{p.furnishingStatus}</div><div className={styles.specKey}>Furnishing</div></div></div>}
              {p.listingType && <div className={styles.specItem}><span className={styles.specIcon} style={{fontSize:18}}>📋</span><div><div className={styles.specVal}>{p.listingType}</div><div className={styles.specKey}>For</div></div></div>}
            </div>

            {/* Owner Info */}
            {p.ownerName && (
              <div className={styles.ownerCard}>
                <div className={styles.ownerAvatar}>{p.ownerName[0]?.toUpperCase()}</div>
                <div>
                  <div className={styles.ownerName}>{p.ownerName}</div>
                  <div className={styles.ownerType}>{p.userType || 'Owner'}</div>
                </div>
              </div>
            )}

            {/* CTA */}
            <button className={styles.enquireBtn} onClick={() => { if (!user) { navigate('/login'); return; } setShowEnquiry(true); }}>
              {p.secondaryCta?.label || 'Enquire Now'}
            </button>
            {p.ownerPhone && (
              <a href={`tel:${p.ownerPhone}`} className={styles.callBtn}>
                <Phone size={16} /> {p.ownerPhone}
              </a>
            )}
          </div>
        </div>
      </div>

      {showEnquiry && <EnquiryModal property={p} onClose={() => setShowEnquiry(false)} />}
    </div>
  );
}
